from pathlib import Path
import json,base64
from PIL import Image,ImageDraw
R=Path.cwd();O=R/'build/graphics/walker_candidates_r88';data=json.loads((O/'data.json').read_text());defs=json.loads((O/'defaults.json').read_text());worker=(O/'worker.js').read_text();js=(R/'src/walker_candidates_r88.js').read_text();safe=lambda x:json.dumps(x,separators=(',',':')).replace('<','\\u003c')
head='''<!doctype html><html><head><meta charset="utf-8"><title>R-Type walker comparisons r88</title><style>:root{--sprite-width:320px}body{background:#111923;color:#e5eef8;font:17px system-ui;margin:20px;max-width:1600px}header{position:sticky;top:0;background:#182434;padding:12px;z-index:2;box-shadow:0 3px 6px #000}h1{font-size:27px;margin:6px 0}button,select{font:inherit;padding:8px;margin:5px}details{border-top:1px solid #52677f;margin:24px 0;padding:16px 0}summary{font-size:23px;cursor:pointer}.panels{display:flex;gap:12px;flex-wrap:wrap;align-items:flex-start}figure{margin:4px;padding:8px;background:#192432;max-width:var(--sprite-width);width:var(--sprite-width)}figcaption{min-height:46px;font-weight:600}canvas{width:100%;height:auto;image-rendering:pixelated;background:black}label{display:flex;justify-content:space-between;align-items:center;font-size:14px;gap:6px}label input{width:65%}output{min-width:35px}small{display:block;color:#adc9e2;max-width:100%;overflow-wrap:anywhere}textarea{display:block;box-sizing:border-box;width:95%;min-height:60px;background:#172432;color:white;font:inherit;padding:10px;margin:8px}img{max-width:100%;image-rendering:pixelated}a{color:#8dd9ff}.notice{background:#28394c;padding:12px}</style></head><body><header><h1>Walker comparisons — preserve approved art, improve the rest</h1><button id="play">Pause animation</button><button id="step">Step pose</button><span id="frame"></span><label style="display:inline-flex">Pose interval <input style="width:120px" id="speed" type="range" min="90" max="600" value="180"></label><label style="display:inline-flex">Zoom <input style="width:90px" id="zoom" type="range" min="3" max="8" value="5"></label><button id="expand">Expand all</button><button id="export">Export choices/settings</button><label style="display:inline-flex">Import JSON <input id="import" type="file" accept="application/json,.json"></label><small id="save">Choices and notes save locally; export JSON to share them.</small></header><p class="notice">Asset comparisons only. Current game files are unchanged by this page. L3_yellow and L3_exhaust are accepted and preserved. Blue_21–25 is kept as requested; confirm the exact saved set below. The other walkers are open for review.</p><section><h2>The saved blue_21–25 set</h2><img src="blue_21_25_keep.png"><p>21/22/23 are walking poses;24/25 are weapon-raising poses, not extra walking frames. Existing pixels are kept unchanged. Any additional stepping frame needs its own review.</p><label>Is this the set to keep? <select id="blue"><option value="pending">Not yet confirmed</option><option value="yes">Yes — keep these exact pixels</option><option value="no">No — different walker/set</option></select></label></section><p>Each editable row shows the earlier baseline, rejected r86 version, source at its target size, and three alternatives. Controls recalculate all four poses together using actual RPC CPU linear adjustments, segment-coverage ECM pairs and serpentine Sierra Lite. This is the CPU conversion stage, not every optional full-app refinement. A keeps the normal RPC candidate list. B/C prevent invented red/magenta speckles by restricting those pairs to cells containing real source-red pixels. Normal8-colour palette, legal8×1 pairs, no bright black, no later BRIGHT normalization.</p><p>Animation is synchronized and can be stepped. Pose interval is illustrative, not game FPS. A conversion can collapse similar poses: each panel reports how many distinct results remain. Sources with uncertain identity and the proposed32×32 L7 size increase are labelled. No new AI replacement sprites are included.</p><main id="groups"></main>'''
(O/'index.html').write_text(head+'<script>const DATA='+safe(data)+';const DEFAULT_IMAGES='+safe(defs)+';const WORKER_TEXT='+safe(worker)+';</script><script>'+js+'</script></body></html>',encoding='utf-8')
# Representative static results; exact default worker output.
canvas=Image.new('RGB',(1120,660),(16,22,30));d=ImageDraw.Draw(canvas)
for row,gid in enumerate(['head32','head24','round3']):
 g=next(g for g in data['groups']if g['id']==gid);d.text((10,row*220+3),g['title'],fill='white')
 for col,(label,f)in enumerate([('Earlier',g['baseline'][0]),('A',defs[gid]['A'][0]),('B',defs[gid]['B'][0]),('C',defs[gid]['C'][0])]):
  im=Image.frombytes('RGB',(f['w'],f['h']),base64.b64decode(f['rgb']));im=im.resize((im.width*5,im.height*5),Image.Resampling.NEAREST);canvas.paste(im,(col*280+10,row*220+38));d.text((col*280+10,row*220+20),label,fill='white')
canvas.save(O/'priority_candidates.png');print('Published local interactive comparisons', (O/'index.html').stat().st_size,'bytes')
